// ==UserScript==
// @name         Dark Elf - Hlídač populace (veřejná verze)
// @namespace    https://github.com/goringardevang-alt/darkelf-hlidac-populace
// @version      5.8
// @description  Na mapě darkelf.cz označí tvé země, kam se nevejde příští přírůstek obyvatel: červeně 0 volných domů, oranžově méně volných domů než přírůstek. Zapíná se tlačítkem s domem tvé rasy na mapě.
// @author       Gorin & Claude
// @match        https://www.darkelf.cz/*
// @match        https://www.darkelf.sk/*
// @grant        none
// @homepageURL  https://github.com/goringardevang-alt/darkelf-hlidac-populace
// @supportURL   https://github.com/goringardevang-alt/darkelf-hlidac-populace/issues
// @updateURL    https://raw.githubusercontent.com/goringardevang-alt/darkelf-hlidac-populace/main/darkelf-hlidac-populace.user.js
// @downloadURL  https://raw.githubusercontent.com/goringardevang-alt/darkelf-hlidac-populace/main/darkelf-hlidac-populace.user.js
// ==/UserScript==

// ─────────────────────────────────────────────────────────────
// Dark Elf - Hlídač populace v5.8
//
// Sestavený soubor — needituj ho, po aktualizaci by se změny ztratily.
// Chyba nebo nápad: https://github.com/goringardevang-alt/darkelf-hlidac-populace/issues
// ─────────────────────────────────────────────────────────────

(function () {
    'use strict';

    const PRUMER_TECKY = 12;

    const IKONY = {
        0: 'data:image/png;base64,',
        1: 'data:image/png;base64,',
        2: 'data:image/png;base64,',
        3: 'data:image/png;base64,',
        4: 'data:image/png;base64,',
        5: 'data:image/png;base64,',
        6: 'data:image/png;base64,',
        7: 'data:image/png;base64,',
        8: 'data:image/png;base64,',
        9: 'data:image/png;base64,',
        10: 'data:image/png;base64,',
    };

    const IKONA_VYCHOZI = 0;

    const NAZEV = 'Dark Elf - Hlídač populace';
    const KLIC_ZAPNUTO = 'de_hlidac_populace_zapnuto';
    const KLIC_SIGNAL = 'de_hlidac_populace_signal';
    const KLIC_ODESLANO = 'de_hlidac_populace_odeslano';
    const KLIC_KOLA = 'de_rounds_remaining';
    const KLIC_RASA = 'de_hlidac_populace_rasa';
    const NAVRAT_MS = 20000;

    if (/^\/world\.htm$/i.test(location.pathname)) {
        try { localStorage.removeItem(KLIC_RASA); } catch (e) {  }
    }

    if (!/^\/map/i.test(location.pathname)) {
        hlidejOdeslani();
        return;
    }

    function hlidejOdeslani() {
        try {
            if (sessionStorage.getItem(KLIC_ODESLANO) === window.name) {
                sessionStorage.removeItem(KLIC_ODESLANO);
                localStorage.setItem(KLIC_SIGNAL, String(Date.now()));
            }
        } catch (e) {  }

        window.addEventListener('submit', (e) => {
            const jmeno = e.target && e.target.getAttribute && e.target.getAttribute('name');
            if (jmeno !== 'form_domy' && jmeno !== 'form_army') return;
            try { sessionStorage.setItem(KLIC_ODESLANO, window.name); } catch (e2) {  }
        }, true);
    }

    let zapnuto = cti(KLIC_ZAPNUTO) === '1';
    let tlacitko = null;
    let bezi = false;
    let znovu = false;
    let posledniKontrola = 0;
    let vysledek = null;
    let chyba = null;

    if (!start()) {
        const obs = new MutationObserver(() => { if (start()) obs.disconnect(); });
        obs.observe(document.documentElement, { childList: true, subtree: true });
        setTimeout(() => obs.disconnect(), 10000);
    }

    function start() {
        const kontejner = document.getElementById('miniMenuContainer');
        if (!kontejner) return false;
        if (document.getElementById('de-hp-tlacitko')) return true;

        pridejStyly();

        tlacitko = document.createElement('img');
        tlacitko.id = 'de-hp-tlacitko';
        tlacitko.className = 'miniMenuItem cursorHand';
        tlacitko.alt = '';
        nastavIkonu();
        tlacitko.addEventListener('click', (e) => {
            e.preventDefault();
            zapnuto = !zapnuto;
            zapis(KLIC_ZAPNUTO, zapnuto ? '1' : '0');
            if (zapnuto) {
                zkontroluj(true);
            } else {
                smazKruhy();
                obnovTlacitko();
            }
        });
        kontejner.appendChild(tlacitko);
        obnovTlacitko();

        window.addEventListener('de-prihlaseni', () => nastavIkonu());
        window.addEventListener('storage', (e) => {
            if (zapnuto && (e.key === KLIC_SIGNAL || e.key === KLIC_KOLA)) zkontroluj(false);
        });
        document.documentElement.addEventListener('mouseenter', () => {
            if (zapnuto && Date.now() - posledniKontrola >= NAVRAT_MS) zkontroluj(false);
        });

        if (zapnuto) zkontroluj(false);
        return true;
    }

    async function zkontroluj(ukazPrubeh) {
        if (!zapnuto) return;
        if (bezi) { znovu = true; return; }
        bezi = true;
        posledniKontrola = Date.now();
        if (ukazPrubeh) obnovTlacitko(true);

        try {
            const doc = await nactiStranku('/auto_domy.asp');
            const zeme = doc && prectiDomy(doc);
            if (!zeme) throw new Error('v auto_domy.asp jsem nenašel žádnou zem');
            if (zapnuto) vykresli(zeme);
            chyba = null;
        } catch (e) {

            console.warn(NAZEV + ':', e.message);
            chyba = e.message;
        } finally {
            bezi = false;
            obnovTlacitko();
            if (znovu) { znovu = false; zkontroluj(false); }
        }
    }

    async function nactiStranku(url) {
        if (window.DarkElfUtils && window.DarkElfUtils.fetchPage) {
            return window.DarkElfUtils.fetchPage(url);
        }
        const res = await fetch(url, { credentials: 'include' });
        const text = new TextDecoder('windows-1250').decode(await res.arrayBuffer());
        return new DOMParser().parseFromString(text, 'text/html');
    }

    function prectiDomy(doc) {
        const zeme = new Map();
        doc.querySelectorAll('form[name="form_domy"] table tr').forEach((tr) => {
            const a = tr.querySelector('a[href^="e.asp?id="]');
            const m = a && (a.getAttribute('href') || '').match(/id=(\d+)/);
            if (!m) return;
            const id = parseInt(m[1], 10);

            const hSpan = doc.getElementById('es' + id + 'h');
            const bunka = hSpan && hSpan.closest('td');
            const vm = bunka && (bunka.textContent || '').match(/\((\d+)\)/);
            if (!vm) return;

            const plus = tr.querySelector('span[style*="color:#33AA33"]');
            const pm = plus && (plus.textContent || '').match(/\+\s*(\d+)/);

            zeme.set(id, {
                jmeno: (a.textContent || '').trim() || ('#' + id),
                volne: parseInt(vm[1], 10),
                prirustek: pm ? parseInt(pm[1], 10) : null
            });
        });
        return zeme.size ? zeme : null;
    }

    function vykresli(zeme) {
        smazKruhy();
        const plno = [], malo = [];

        zeme.forEach((z, id) => {
            let typ = null;
            if (z.volne === 0) {
                typ = 'plno';
                plno.push(z.jmeno);
            } else if (z.prirustek !== null && z.volne < z.prirustek) {
                typ = 'malo';
                malo.push(z.jmeno + ' (' + z.volne + ' < +' + z.prirustek + ')');
            }
            if (!typ) return;

            const land = document.getElementById('x' + id);
            if (!land || !land.parentElement) return;

            const cs = getComputedStyle(land);
            const l = parseFloat(cs.left), t = parseFloat(cs.top);
            const x = isNaN(l) ? land.offsetLeft : l;
            const y = isNaN(t) ? land.offsetTop : t;
            const w = parseFloat(cs.width) || land.offsetWidth;
            const h = parseFloat(cs.height) || land.offsetHeight;
            const d = PRUMER_TECKY;

            const kruh = document.createElement('div');
            kruh.className = 'de-hp-kruh de-hp-' + typ;
            kruh.dataset.id = String(id);
            kruh.style.left = Math.round(x + (w - d) / 2) + 'px';
            kruh.style.top = Math.round(y + (h - d) / 2) + 'px';
            kruh.style.width = d + 'px';
            kruh.style.height = d + 'px';
            land.parentElement.appendChild(kruh);
        });

        vysledek = { plno, malo, cas: new Date() };
    }

    function smazKruhy() {
        document.querySelectorAll('.de-hp-kruh').forEach((k) => k.remove());
    }

    function pridejStyly() {
        if (document.getElementById('de-hp-styly')) return;
        const st = document.createElement('style');
        st.id = 'de-hp-styly';

        st.textContent = `
            .de-hp-kruh { position: absolute; box-sizing: border-box; border-radius: 50%;
                          pointer-events: none; z-index: 10; }
            .de-hp-plno { background: rgba(255, 30, 30, 0.95); border: 1px solid rgba(0, 0, 0, 0.6);
                          box-shadow: 0 0 3px 1px rgba(255, 0, 0, 0.6); }
            .de-hp-malo { background: rgba(255, 150, 0, 0.95); border: 1px solid rgba(0, 0, 0, 0.6);
                          box-shadow: 0 0 3px 1px rgba(255, 140, 0, 0.6); }
            #de-hp-tlacitko.de-hp-vypnuto { opacity: 0.45; filter: grayscale(1); }
            #de-hp-tlacitko.de-hp-prubeh  { opacity: 0.7; }
            #de-hp-tlacitko.de-hp-chyba   { filter: sepia(1) saturate(6) hue-rotate(-40deg); }
        `;
        document.head.appendChild(st);
    }

    function nastavIkonu() {
        if (!tlacitko) return;
        const U = window.DarkElfUtils;
        if (!U || !U.Prihlaseni || !U.MapAPI) { rasaBezJadra(); return; }
        const id = rasaZeSnimku();
        tlacitko.src = IKONY[id !== null ? id : IKONA_VYCHOZI];
        const moje = U.Prihlaseni.mojeZemNaMape(document);
        if (id !== null || !moje) return;

        const zemVeSnimku = !!U.MapAPI.getCountry(moje.id);
        U.MapAPI.fetch(null, zemVeSnimku)
            .then(() => { const nova = rasaZeSnimku(); if (nova !== null) tlacitko.src = IKONY[nova]; })
            .catch(() => {  });
    }

    function rasaZeSnimku() {
        const U = window.DarkElfUtils;
        if (!U || !U.Prihlaseni || !U.MapAPI) return null;
        const moje = U.Prihlaseni.mojeZemNaMape(document);
        const ja = U.MapAPI.getMe();
        if (!moje || !ja || ja.id !== moje.hrac) return null;
        const z = U.MapAPI.getCountry(moje.id);
        if (!z || String(z.id_hrac) !== ja.id || !IKONY[z.id_rasa]) return null;
        return Number(z.id_rasa);
    }

    async function rasaBezJadra() {
        const ulozena = ctiJson(KLIC_RASA);
        if (ulozena) {
            tlacitko.src = IKONY[ulozena.id_rasa] || IKONY[IKONA_VYCHOZI];
            return;
        }
        tlacitko.src = IKONY[IKONA_VYCHOZI];
        const rasa = await rasaZExportu();
        if (rasa !== null && IKONY[rasa]) tlacitko.src = IKONY[rasa];
    }

    async function rasaZExportu() {
        for (let pokus = 1; pokus <= 2; pokus++) {
            let data;
            try {
                const res = await fetch('/map_export_json.asp', { credentials: 'include' });
                data = await res.json();
            } catch (e) {
                return null;
            }

            if (data && data.error) {
                if (pokus === 2) return null;
                const s = Number(data.retry_after);
                await new Promise((r) => setTimeout(r, (Number.isFinite(s) && s > 0 ? s : 1) * 1000 + 300));
                continue;
            }
            const ja = data && data.hlavicka ? data.hlavicka.id_hrace : null;
            if (ja == null || !Array.isArray(data.zeme)) return null;
            const zem = data.zeme.find((z) => z && z.id_hrac != null && String(z.id_hrac) === String(ja));
            const rasa = zem && IKONY[zem.id_rasa] ? Number(zem.id_rasa) : null;

            zapis(KLIC_RASA, JSON.stringify({ id_hrace: ja, id_rasa: rasa }));
            return rasa;
        }
        return null;
    }

    function obnovTlacitko(prubeh) {
        if (!tlacitko) return;
        tlacitko.classList.toggle('de-hp-vypnuto', !zapnuto);
        tlacitko.classList.toggle('de-hp-prubeh', !!(zapnuto && prubeh));
        tlacitko.classList.toggle('de-hp-chyba', !!(zapnuto && !prubeh && chyba));
        if (!zapnuto) {
            tlacitko.title = 'Hlídač populace: vypnuto\nKlik = zapnout';
            return;
        }

        const radky = ['Hlídač populace: zapnuto'];
        if (prubeh) radky.push('Stahuji auto_domy.asp…');
        if (chyba) radky.push('Chyba: ' + chyba);
        if (vysledek) {
            radky.push('🔴 Plno (0 volných): ' + (vysledek.plno.join(', ') || '—'));
            radky.push('🟠 Nevejde se přírůstek: ' + (vysledek.malo.join(', ') || '—'));
            radky.push((chyba ? 'Poslední úspěšná kontrola: ' : 'Zkontrolováno: ')
                + vysledek.cas.toLocaleTimeString('cs-CZ'));
        }
        radky.push('Klik = vypnout');
        tlacitko.title = radky.join('\n');
    }

    function cti(klic) {
        try { return localStorage.getItem(klic); } catch (e) { return null; }
    }

    function ctiJson(klic) {
        try { return JSON.parse(cti(klic)) || null; } catch (e) { return null; }
    }

    function zapis(klic, hodnota) {
        try { localStorage.setItem(klic, hodnota); } catch (e) {  }
    }

})();
